 1587          } else {
 1588              // No chat will show to end the interval; a cancelled open is ended by
 1589              // the newer `begin` instead.
 1590              SessionOpenSignpost.end(sessionID: session.sessionId, messages: nil)
 1591          }
 1592      }
 1593  
 1594      private var sessionOpenErrorIsPresented: Binding<Bool> {
 1595          Binding(
 1596              get: { sessionOpenErrorMessage != nil },
